void WLibraryScanStatus::refresh() {
    if (!m_controller) {
        return;
    }
    m_scan->setEnabled(!m_controller->isActive());
    m_cancel->setEnabled(m_controller->isActive() && !m_controller->isCancelling());
    m_status->setText(m_controller->status());
    m_status->setToolTip(m_controller->currentPath().isEmpty()
                    ? m_controller->status() : m_controller->currentPath());
    const auto progress = m_controller->progress();
    m_progress->setRange(0, progress < 0 ? 0 : 100);
    if (progress >= 0) {
        m_progress->setValue(progress);
    }
    m_progress->setVisible(m_controller->isActive() || progress > 0);
}
